                let y = f32(i32(idx & 2u) * 2 - 1);
                out.position = vec4<f32>(x, y, 0.0, 1.0);
                out.uv = vec2<f32>(x * 0.5 + 0.5, 1.0 - (y * 0.5 + 0.5));
