    let z = index / grid_xy;
    let y = (index % grid_xy) / params.grid_x;
    let x = index % params.grid_x;
    let id0 = vec3<u32>(x, y, z);

    if (id0.x == 0u || id0.y == 0u || id0.z == 0u || id0.x >= params.grid_x - 2u || id0.y >= params.grid_y - 2u || id0.z >= params.grid_z - 2u) {{
        return 0u;
