r#"
fn ordered_from_float(value: f32) -> u32 {
    let bits = bitcast<u32>(value);
    if ((bits & 0x80000000u) != 0u) {
        return ~bits;
    }
    return bits | 0x80000000u;
}

fn float_from_ordered(bits: u32) -> f32 {
    if ((bits & 0x80000000u) != 0u) {
        return bitcast<f32>(bits & 0x7FFFFFFFu);
    }
    return bitcast<f32>(~bits);
}
