    atomicMin(&node_bounds[node * 6u + 1u], ordered_from_float(lower.y));
    atomicMin(&node_bounds[node * 6u + 2u], ordered_from_float(lower.z));
    atomicMax(&node_bounds[node * 6u + 3u], ordered_from_float(upper.x));
