@group(0) @binding(6) var<storage, read_write> cand_normal: array<vec4<f32>>;
@group(0) @binding(7) var<storage, read_write> keep: array<u32>;

struct Params {
    count: u32,
    triangles: u32,
    seed: u32,
    balding: u32,
    total_area: f32,
    crown: f32,
    temples: f32,
    top: f32,
    patchiness: f32,
    edge: f32,
    offset_x: f32,
    offset_y: f32,
    offset_z: f32,
